query context_transition {
 require $unit HAS_FIELD $state;
 require $unit INSTANCE_RECEIVER $self;
 require $unit HAS_METHOD $setup;
 callable(constructor: true) as $setup;
 require $setup HAS_CALL $initial;
 require $state ASSIGNED_FROM $initial;
 require $initial ALLOCATES_TYPE $concrete;
 require $initial CONSTRUCTOR_TARGET $constructor;
 require $initial CALL_BINDING $binding [mode: direct];
 require $binding BINDING_TARGET $constructor;
 require $binding BINDING_VALUE $self;
 require $binding BINDING_PARAMETER $context_input;
 require $backref CONSTRUCTOR_FIELD_INPUT $context_input;
 require $concrete HAS_FIELD $backref;
 require $unit HAS_METHOD $request;
 callable(constructor: false) as $request;
 require $request HAS_CALL $dispatch;
 require $dispatch RECEIVER $state;
 any { require $dispatch TARGET $slot; }
 or { require $dispatch DECLARED_TARGET $slot; }
 require $concrete HAS_METHOD $action;
 any { require $dispatch TARGET $action; }
 or { require $action OVERRIDES $slot; }
 require $unit HAS_METHOD $setter;
 callable(constructor: false) as $setter;
 require $setter HAS_PARAMETER $replacement;
 require $setter HAS_OPERATION $write;
 require $write ASSIGNMENT_TARGET $state;
 require $write FINAL_FIELD_INPUT $replacement;
 require $action HAS_CALL $transition;
 require $transition RECEIVER $backref;
 any {
  require $transition TARGET $setter;
  require $transition CALL_BINDING $supplied [mode: direct];
  require $supplied BINDING_TARGET $setter;
  require $supplied BINDING_PARAMETER $replacement;
  require $supplied BINDING_VALUE $creation;
 } or {
  variable(type_state: unknown) as $backref;
  call(resolution: unresolved) as $transition;
  callable(arity: 1) as $setter;
  where $transition.name == $setter.name;
  require $setter HAS_PARAMETER $replacement [position: 0, kind: positional];
  require $transition ARGUMENT $argument;
  require $argument ENTITY ARGUMENT [position: 0, kind: positional];
  require $argument VALUE $result;
  require $creation RESULT $result;
 }
 require $creation ALLOCATES_TYPE $next;
 different $concrete $next;
 path $concrete SUBTYPE_OF{1,8} $contract as $current_contract;
 path $next SUBTYPE_OF{1,8} $contract as $next_contract;
 emit $unit, $state, $setup, $initial, $constructor, $context_input, $backref, $request, $dispatch, $slot, $action, $setter, $replacement, $write, $transition, $creation, $next;
}

